}

.proposal-row > span {
  min-width: 0;
}

.proposal-customer,
.proposal-outing,
.proposal-price {
  display: grid;
  gap: 0.2rem;
}

.proposal-row strong,
.proposal-row small {
  display: block;
  overflow: hidden;
